use clap::{Arg, Command, value_parser, builder::PossibleValuesParser};
use std::net::{SocketAddr, IpAddr};

fn parse_bytes(s: &str) -> Result<u64, std::num::ParseIntError> {
    let st = s.trim();
    let (num, mult): (&str, u64) = if st.ends_with('k') {
        (&st[..st.len()-1], 1024)
    } else if st.ends_with('M') {
        (&st[..st.len()-1], 1024*1024)
    } else if st.ends_with('G') {
        (&st[..st.len()-1], 1024*1024*1024)
    } else if st.ends_with('T') {
        (&st[..st.len()-1], 1024u64*1024*1024*1024)
    } else {
        (st, 1)
    };
    let v: u64 = num.parse()?;
    Ok(v.wrapping_mul(mult))
}

fn build_cli() -> Command {
    let send_arg = |name: &str| {
        Arg::new(name)
            .long(name)
            .value_name("SEND_BUFFER_SIZE")
            .default_value("2M")
            .help("Send buffer size in bytes")
            .long_help("Send buffer size in bytes\n\nThis can use SI suffixes for sizes. For example, 1M will request 1MiB, 10G will request 10GiB.")
            .value_parser(parse_bytes)
    };
    // We'll build fully later; for now minimal to test
    Command::new("executable")
        .subcommand(
            Command::new("server").about("Run as a perf server")
                .arg(Arg::new("listen").long("listen").value_name("LISTEN").default_value("[::]:4433").help("Address to listen on").value_parser(value_parser!(SocketAddr)))
                .arg(Arg::new("key").short('k').long("key").value_name("KEY").help("TLS private key in DER format"))
                .arg(Arg::new("cert").short('c').long("cert").value_name("CERT").help("TLS certificate in PEM format"))
                .arg(Arg::new("send-buffer-size").long("send-buffer-size").value_name("SEND_BUFFER_SIZE").default_value("2M").help("Send buffer size in bytes").long_help("Send buffer size in bytes\n\nThis can use SI suffixes for sizes. For example, 1M will request 1MiB, 10G will request 10GiB.").value_parser(parse_bytes))
                .arg(Arg::new("recv-buffer-size").long("recv-buffer-size").value_name("RECV_BUFFER_SIZE").default_value("2M").help("Receive buffer size in bytes").long_help("Receive buffer size in bytes\n\nThis can use SI suffixes for sizes. For example, 1M will request 1MiB, 10G will request 10GiB.").value_parser(parse_bytes))
                .arg(Arg::new("conn-stats").long("conn-stats").help("Whether to print connection statistics").action(clap::ArgAction::SetTrue))
                .arg(Arg::new("keylog").long("keylog").help("Perform NSS-compatible TLS key logging to the file specified in `SSLKEYLOGFILE`").action(clap::ArgAction::SetTrue))
                .arg(Arg::new("initial-mtu").long("initial-mtu").value_name("INITIAL_MTU").default_value("1200").help("UDP payload size that the network must be capable of carrying").value_parser(value_parser!(u16)))
                .arg(Arg::new("no-protection").long("no-protection").help("Disable packet encryption/decryption (for debugging purpose)").action(clap::ArgAction::SetTrue))
                .arg(Arg::new("initial-rtt").long("initial-rtt").value_name("INITIAL_RTT").help("The initial round-trip-time (in msecs)").value_parser(value_parser!(u64)))
                .arg(Arg::new("ack-frequency").long("ack-frequency").help("Ack Frequency mode").action(clap::ArgAction::SetTrue))
                .arg(Arg::new("congestion").long("congestion").value_name("CONG_ALG").help("Congestion algorithm to use").value_parser(PossibleValuesParser::new(["cubic","bbr","new-reno"])))
                .arg(Arg::new("stream-receive-window").long("stream-receive-window").value_name("STREAM_RECEIVE_WINDOW").help("Maximum number of bytes the peer may transmit without acknowledgement on any one stream before becoming blocked.").long_help("Maximum number of bytes the peer may transmit without acknowledgement on any one stream before becoming blocked.\n\nThis can use SI suffixes for sizes. For example, 1M will limit to 1MiB, 10G will limit to 10GiB.").value_parser(parse_bytes))
                .arg(Arg::new("receive-window").long("receive-window").value_name("RECEIVE_WINDOW").help("Maximum number of bytes the peer may transmit across all streams of a connection before becoming blocked.").long_help("Maximum number of bytes the peer may transmit across all streams of a connection before becoming blocked.\n\nThis can use SI suffixes for sizes. For example, 1M will limit to 1MiB, 10G will limit to 10GiB.").value_parser(parse_bytes))
                .arg(Arg::new("send-window").long("send-window").value_name("SEND_WINDOW").help("Maximum number of bytes to transmit to a peer without acknowledgment").long_help("Maximum number of bytes to transmit to a peer without acknowledgment\n\nThis can use SI suffixes for sizes. For example, 1M will limit to 1MiB, 10G will limit to 10GiB.").value_parser(parse_bytes))
                .arg(Arg::new("max-udp-payload-size").long("max-udp-payload-size").value_name("MAX_UDP_PAYLOAD_SIZE").default_value("1472").help("Max UDP payload size in bytes").value_parser(value_parser!(u16)))
                .arg(Arg::new("qlog").long("qlog").value_name("QLOG_FILE").help("qlog output file"))
        )
        .subcommand(
            Command::new("client").about("Run as a perf client")
                .arg(Arg::new("host").default_value("localhost:4433").help("Host to connect to"))
                .arg(Arg::new("ip").long("ip").value_name("IP").help("Override DNS resolution for host").value_parser(value_parser!(IpAddr)))
                .arg(Arg::new("local-addr").long("local-addr").value_name("LOCAL_ADDR").help("Specify the local socket address").value_parser(value_parser!(SocketAddr)))
                .arg(Arg::new("uni-requests").long("uni-requests").value_name("UNI_REQUESTS").default_value("0").help("Number of unidirectional requests to maintain concurrently").value_parser(value_parser!(u64)))
                .arg(Arg::new("bi-requests").long("bi-requests").value_name("BI_REQUESTS").default_value("1").help("Number of bidirectional requests to maintain concurrently").value_parser(value_parser!(u64)))
                .arg(Arg::new("download-size").long("download-size").value_name("DOWNLOAD_SIZE").default_value("1M").help("Number of bytes to request").long_help("Number of bytes to request\n\nThis can use SI suffixes for sizes. For example, 1M will transfer 1MiB, 10G will transfer 10GiB.").value_parser(parse_bytes))
                .arg(Arg::new("upload-size").long("upload-size").value_name("UPLOAD_SIZE").default_value("1M").help("Number of bytes to transmit, in addition to the request header").long_help("Number of bytes to transmit, in addition to the request header\n\nThis can use SI suffixes for sizes. For example, 1M will transfer 1MiB, 10G will transfer 10GiB.").value_parser(parse_bytes))
                .arg(Arg::new("duration").long("duration").value_name("DURATION").default_value("60").help("The time to run in seconds").value_parser(value_parser!(u64)))
                .arg(Arg::new("interval").long("interval").value_name("INTERVAL").default_value("1").help("The interval in seconds at which stats are reported").value_parser(value_parser!(u64)))
                .arg(Arg::new("json").long("json").value_name("JSON").help("File path to output JSON statistics to. If the file is '-', stdout will be used"))
                .arg(Arg::new("send-buffer-size").long("send-buffer-size").value_name("SEND_BUFFER_SIZE").default_value("2M").help("Send buffer size in bytes").long_help("Send buffer size in bytes\n\nThis can use SI suffixes for sizes. For example, 1M will request 1MiB, 10G will request 10GiB.").value_parser(parse_bytes))
                .arg(Arg::new("recv-buffer-size").long("recv-buffer-size").value_name("RECV_BUFFER_SIZE").default_value("2M").help("Receive buffer size in bytes").long_help("Receive buffer size in bytes\n\nThis can use SI suffixes for sizes. For example, 1M will request 1MiB, 10G will request 10GiB.").value_parser(parse_bytes))
                .arg(Arg::new("conn-stats").long("conn-stats").help("Whether to print connection statistics").action(clap::ArgAction::SetTrue))
                .arg(Arg::new("keylog").long("keylog").help("Perform NSS-compatible TLS key logging to the file specified in `SSLKEYLOGFILE`").action(clap::ArgAction::SetTrue))
                .arg(Arg::new("initial-mtu").long("initial-mtu").value_name("INITIAL_MTU").default_value("1200").help("UDP payload size that the network must be capable of carrying").value_parser(value_parser!(u16)))
                .arg(Arg::new("no-protection").long("no-protection").help("Disable packet encryption/decryption (for debugging purpose)").action(clap::ArgAction::SetTrue))
                .arg(Arg::new("initial-rtt").long("initial-rtt").value_name("INITIAL_RTT").help("The initial round-trip-time (in msecs)").value_parser(value_parser!(u64)))
                .arg(Arg::new("ack-frequency").long("ack-frequency").help("Ack Frequency mode").action(clap::ArgAction::SetTrue))
                .arg(Arg::new("congestion").long("congestion").value_name("CONG_ALG").help("Congestion algorithm to use").value_parser(PossibleValuesParser::new(["cubic","bbr","new-reno"])))
                .arg(Arg::new("stream-receive-window").long("stream-receive-window").value_name("STREAM_RECEIVE_WINDOW").help("Maximum number of bytes the peer may transmit without acknowledgement on any one stream before becoming blocked.").long_help("Maximum number of bytes the peer may transmit without acknowledgement on any one stream before becoming blocked.\n\nThis can use SI suffixes for sizes. For example, 1M will limit to 1MiB, 10G will limit to 10GiB.").value_parser(parse_bytes))
                .arg(Arg::new("receive-window").long("receive-window").value_name("RECEIVE_WINDOW").help("Maximum number of bytes the peer may transmit across all streams of a connection before becoming blocked.").long_help("Maximum number of bytes the peer may transmit across all streams of a connection before becoming blocked.\n\nThis can use SI suffixes for sizes. For example, 1M will limit to 1MiB, 10G will limit to 10GiB.").value_parser(parse_bytes))
