// Logging
fn timestamp_now() -> String {
    let now = chrono::Utc::now();
    now.format("%Y-%m-%dT%H:%M:%S%.6fZ").to_string()
}
fn level_enabled(level: &str) -> bool {
    let rl = std::env::var("RUST_LOG").unwrap_or_default().to_lowercase();
    if rl.is_empty() {
        return level == "WARN" || level == "ERROR";
    }
    // check for substrings
    let has_trace = rl.contains("trace");
    let has_debug = rl.contains("debug");
    let has_info = rl.contains("info");
    let has_warn = rl.contains("warn");
    let has_error = rl.contains("error");
    match level {
        "ERROR" => true,
        "WARN" => has_warn || has_info || has_debug || has_trace || rl.is_empty(),
        "INFO" => has_info || has_debug || has_trace,
        "DEBUG" => has_debug || has_trace,
        "TRACE" => has_trace,
        _ => false,
    }
}
fn print_log(level: &str, target: &str, msg: &str) {
    if !level_enabled(level) { return; }
    let ts = timestamp_now();
    let no_color = std::env::var_os("NO_COLOR").is_some();
    if no_color {
        let lvl_padded = format!("{:>5}", level);
        // format: "TS LVL TARGET: MSG"
        // Actually observed: "TS  WARN perf: ..." -> TS + " " + padded LVL? Let's do TS + " " + padded + " " + target + ": " + msg
        // For WARN, padded is " WARN" (5), so TS + " " + " WARN" + " " + ...
        // That gives TS + "  WARN ..." (two spaces after TS for WARN). For ERROR, padded "ERROR" (5), TS + " " + "ERROR" + " " => one space after TS.
        // This matches observed: WARN has two spaces, ERROR has one.
        println!("{} {} {}: {}", ts, lvl_padded, target, msg);
    } else {
        let color = match level {
            "ERROR" => "31",
            "WARN" => "33",
            "INFO" => "32",
            "DEBUG" => "34",
            _ => "0",
        };
        let lvl_padded = format!("{:>5}", level);
        // \x1b[2mTS\x1b[0m \x1b[COLORmLVL\x1b[0m \x1b[2mTARGET\x1b[0m\x1b[2m:\x1b[0m MSG
        println!("\x1b[2m{}\x1b[0m \x1b[{}m{}\x1b[0m \x1b[2m{}\x1b[0m\x1b[2m:\x1b[0m {}", ts, color, lvl_padded, target, msg);
    }
}
fn log_warn(t: &str, m: &str) { print_log("WARN", t, m); }
fn log_error(t: &str, m: &str) { print_log("ERROR", t, m); }
fn log_info(t: &str, m: &str) { print_log("INFO", t, m); }
fn log_debug(t: &str, m: &str) { print_log("DEBUG", t, m); }
fn log_error_quinn_perf(m: &str) { print_log("ERROR", "quinn_perf", m); }

fn get_actual_buffer(desired: u64, is_send: bool) -> u64 {
    unsafe {
        let fd = libc::socket(libc::AF_INET, libc::SOCK_DGRAM, 0);
        if fd < 0 { return 425984; }
        let opt = if is_send { libc::SO_SNDBUF } else { libc::SO_RCVBUF };
        let val: libc::c_int = desired as libc::c_int;
        libc::setsockopt(fd, libc::SOL_SOCKET, opt, &val as *const _ as *const libc::c_void, std::mem::size_of_val(&val) as libc::socklen_t);
        let mut actual: libc::c_int = 0;
        let mut len = std::mem::size_of_val(&actual) as libc::socklen_t;
        libc::getsockopt(fd, libc::SOL_SOCKET, opt, &mut actual as *mut _ as *mut libc::c_void, &mut len);
        libc::close(fd);
        if actual < 0 { 0 } else { actual as u64 }
    }
}
fn check_buffers(send: u64, recv: u64) {
    let actual_send = get_actual_buffer(send, true);
    if actual_send < send {
        log_warn("perf", &format!("Unable to set desired send buffer size. Desired: {}, Actual: {}", send, actual_send));
    }
    let actual_recv = get_actual_buffer(recv, false);
    if actual_recv < recv {
        log_warn("perf", &format!("Unable to set desired recv buffer size. Desired: {}, Actual: {}", recv, actual_recv));
    }
}

