fn connect_with_local(remote: &SocketAddr, local: Option<&SocketAddr>) -> std::io::Result<TcpStream> {
    if let Some(la) = local {
        // Use TcpSocket if available
        #[cfg(unix)]
        {
            use std::os::unix::io::{FromRawFd, AsRawFd};
            let domain = if la.is_ipv4() { libc::AF_INET } else { libc::AF_INET6 };
            unsafe {
                let fd = libc::socket(domain, libc::SOCK_STREAM, 0);
                if fd < 0 { return Err(std::io::Error::last_os_error()); }
                // bind
                let (addr_ptr, addr_len) = socketaddr_to_libc(la);
                let bind_res = libc::bind(fd, addr_ptr as *const libc::sockaddr, addr_len);
                if bind_res != 0 {
                    let e = std::io::Error::last_os_error();
                    libc::close(fd);
                    return Err(e);
                }
                // connect with timeout? Use blocking connect (may hang for unreachable? For 127.0.0.1:1 with no server, connect fails immediately with refused, not hang. For our unreachable hang case, original hangs (retry), not immediate fail. Our pre-check with immediate fail would not hang. Hmm.
                // For 127.0.0.1:1, connect fails immediately (refused). Original hangs (doesn't exit). So our pre-check that hangs on fail would hang, matching. Good.
                // For 127.0.0.1:19999 with no server, connect fails immediately, we hang. Good.
                let (r_ptr, r_len) = socketaddr_to_libc(remote);
                let conn_res = libc::connect(fd, r_ptr as *const libc::sockaddr, r_len);
                if conn_res != 0 {
                    let e = std::io::Error::last_os_error();
                    libc::close(fd);
                    return Err(e);
                }
                // Set timeouts? No.
                Ok(TcpStream::from_raw_fd(fd))
            }
        }
        #[cfg(not(unix))]
        {
            TcpStream::connect(remote)
        }
    } else {
        TcpStream::connect(remote)
    }
}

fn socketaddr_to_libc(addr: &SocketAddr) -> (libc::sockaddr_storage, libc::socklen_t) {
    unsafe {
        let mut storage: libc::sockaddr_storage = std::mem::zeroed();
        let len = match addr {
            SocketAddr::V4(v4) => {
                let mut sa: libc::sockaddr_in = std::mem::zeroed();
                sa.sin_family = libc::AF_INET as u16;
                sa.sin_port = v4.port().to_be();
                sa.sin_addr.s_addr = u32::from_ne_bytes(v4.ip().octets()).to_be();
                // Actually need network order? v4.ip().octets() to s_addr: s_addr is network order (big endian). Use u32::from(v4.ip())? Let's do: let ip = u32::from(*v4.ip()); sa.sin_addr.s_addr = ip.to_be();
                // Simpler: copy bytes
                std::ptr::copy_nonblocking(&sa as *const _ as *const u8, &mut storage as *mut _ as *mut u8, std::mem::size_of::<libc::sockaddr_in>());
                std::mem::size_of::<libc::sockaddr_in>() as libc::socklen_t
            }
            SocketAddr::V6(v6) => {
                let mut sa: libc::sockaddr_in6 = std::mem::zeroed();
                sa.sin6_family = libc::AF_INET6 as u16;
                sa.sin6_port = v6.port().to_be();
                sa.sin6_addr.s6_addr = v6.ip().octets();
                sa.sin6_flowinfo = v6.flowinfo();
                sa.sin6_scope_id = v6.scope_id();
                std::ptr::copy_nonblocking(&sa as *const _ as *const u8, &mut storage as *mut _ as *mut u8, std::mem::size_of::<libc::sockaddr_in6>());
                std::mem::size_of::<libc::sockaddr_in6>() as libc::socklen_t
            }
        };
        (storage, len)
    }
}

