fn do_single_request(remote: &SocketAddr, local: Option<&SocketAddr>, download_sz: u64, upload_sz: u64) -> Option<ReqRecord> {
    let start = Instant::now();
    let mut stream = match connect_with_local(remote, local) {
        Ok(s) => s,
        Err(_) => return None,
    };
    // Send header: 8-byte download BE (with high bit for uni? Caller handles? For now, just download)
    // Actually caller for uni vs bi needs to set high bit? Our workers for uni currently call same do_single_request without flag. Need to pass is_uni.
    // For now, ignore uni flag, just send download.
    if stream.write_all(&download_sz.to_be_bytes()).is_err() { return None; }
    // Send upload bytes
    let chunk = [0u8; 8192];
    let mut remaining = upload_sz;
    while remaining > 0 {
        let n = std::cmp::min(remaining, 8192) as usize;
        if stream.write_all(&chunk[..n]).is_err() { return None; }
        remaining -= n as u64;
    }
    // Shutdown write to signal EOF
    let _ = stream.shutdown(std::net::Shutdown::Write);
    let upload_end = Instant::now();
    // Read download: first byte timing
    let mut first = true;
    let mut fbl = 0u64;
    let mut total_read: u64 = 0;
    let mut buf = [0u8; 8192];
    let first_start = upload_end;
    loop {
        match stream.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => {
                if first {
                    fbl = first_start.elapsed().as_nanos() as u64;
                    first = false;
                }
                total_read += n as u64;
                if total_read >= download_sz { 
                    // Need to read exactly download_sz? Server sends exactly download_sz, then closes. So break when total >= download_sz? But server closes after, so next read will be 0. For now, continue until 0 or enough.
                    // If download_sz is huge (e.g., 1M), total will reach exactly. Break to avoid waiting for close? Server closes after sending, so next read 0 will come quickly. Good.
                    // To be efficient, break when enough.
                    if total_read >= download_sz { break; }
                }
            }
            Err(_) => return None,
        }
    }
    let end = Instant::now();
    let upload_nanos = upload_end.duration_since(start).as_nanos() as u64;
    let download_nanos = if first { 0 } else { end.duration_since(upload_end).as_nanos() as u64 - fbl + 0 }; // Actually download duration should be from first byte to end? Or from upload_end to end? Let's use end - first_byte_time.
    // For first==false, download_nanos = end - (upload_end+fbl) = end - first_byte_time
    // For first==true (no bytes? download 0), download 0, fbl 0? Original for download 0? Not tested. For 0, download duration 0?
    // Simplify: if download_sz==0, download 0, fbl 0.
    let (download_nanos, fbl_nanos) = if download_sz == 0 {
        (0, 0)
    } else if first {
        // No bytes read? Should not happen if server sent correctly. Return None?
        (0, 0)
    } else {
        let first_time = upload_end + Duration::from_nanos(fbl);
        let down = end.duration_since(first_time).as_nanos() as u64;
        (down, fbl)
    };
    Some(ReqRecord { upload_nanos, download_nanos, fbl_nanos, upload_bytes: upload_sz, download_bytes: download_sz })
}

fn write_json(m: &clap::ArgMatches, root: &JsonRoot) {
    if let Some(path) = m.get_one::<String>("json") {
        if path == "-" {
            println!("{}", serde_json::to_string(root).unwrap());
        } else {
            match std::fs::File::create(path) {
                Ok(f) => {
                    let _ = serde_json::to_writer(f, root);
                }
                Err(e) => {
                    log_error_quinn_perf(&format!("{}", e));
                }
            }
        }
    }
}

